  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 10 * s, padding: 16 * s }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1 * s }}>
          <div style={{ fontSize: 15 * s, fontWeight: 700, letterSpacing: '-0.01em', lineHeight: 1.1 }}>{monthName} <span style={{ color: 'var(--w-mut)', fontWeight: 600 }}>{view.y}</span></div>
          <div style={{ fontSize: 10.5 * s, color: 'var(--w-mut)', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{monthEntries.length} post{monthEntries.length === 1 ? '' : 's'} · {publishedCount} live</div>
        </div>
        {!mini && (
          <div style={{ display: 'flex', gap: 4 * s }}>
            <button onClick={() => shift(-1)} aria-label="Previous month" style={{ width: 26 * s, height: 26 * s, display: 'grid', placeItems: 'center', borderRadius: 7 * s, border: '1px solid var(--w-line)', background: 'transparent', color: 'var(--w-fg)', cursor: 'pointer' }}>
              <svg width={12 * s} height={12 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M15 6l-6 6 6 6" /></svg>
            </button>
            <button onClick={() => shift(1)} aria-label="Next month" style={{ width: 26 * s, height: 26 * s, display: 'grid', placeItems: 'center', borderRadius: 7 * s, border: '1px solid var(--w-line)', background: 'transparent', color: 'var(--w-fg)', cursor: 'pointer' }}>
              <svg width={12 * s} height={12 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M9 6l6 6-6 6" /></svg>
            </button>
          </div>
