renderer:
function CalculatorW({ config: c, accent, s, fontStack, mini }) {
  const mode = c.mode || 'basic';
  const precision = typeof c.precision === 'number' ? c.precision : 2;

  const round = (n) => {
    if (!isFinite(n)) return '0';
    const p = Math.pow(10, precision);
    let r = Math.round((n + Number.EPSILON) * p) / p;
    if (Object.is(r, -0)) r = 0;
    let str = r.toFixed(precision);
    if (precision > 0) str = str.replace(/\.?0+$/, '');
    return str;
  };

  const fmtNum = (str) => {
    if (str === '' || str === '-') return str;
    const neg = str.startsWith('-');
    let body = neg ? str.slice(1) : str;
    const [intPart, decPart] = body.split('.');
    const withSep = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return (neg ? '-' : '') + withSep + (decPart !== undefined ? '.' + decPart : '');
  };

  // ---- BASIC CALCULATOR ----
  function Basic() {
    const [acc, setAcc] = useState(null);
    const [op, setOp] = useState(null);
    const [cur, setCur] = useState('0');
    const [fresh, setFresh] = useState(true);
    const [hist, setHist] = useState('');

    const compute = (a, b, o) => {
      a = parseFloat(a); b = parseFloat(b);
      if (o === '+') return a + b;
      if (o === '-') return a - b;
      if (o === '×') return a * b;
      if (o === '÷') return b === 0 ? NaN : a / b;
      return b;
    };

    const inputDigit = (d) => {
      if (fresh) { setCur(d); setFresh(false); return; }
      if (cur === '0') { setCur(d); return; }
      if (cur.replace(/[-.]/g, '').length >= 12) return;
      setCur(cur + d);
    };
    const inputDot = () => {
      if (fresh) { setCur('0.'); setFresh(false); return; }
      if (!cur.includes('.')) setCur(cur + '.');
    };
    const toggleSign = () => {
      if (cur === '0' || cur === 'Error') return;
      setCur(cur.startsWith('-') ? cur.slice(1) : '-' + cur);
    };
    const percent = () => {
      const v = parseFloat(cur) / 100;
      setCur(round(v)); setFresh(true);
    };
    const clearAll = () => { setAcc(null); setOp(null); setCur('0'); setFresh(true); setHist(''); };
    const del = () => {
      if (fresh || cur === 'Error') return;
      if (cur.length <= 1 || (cur.length === 2 && cur.startsWith('-'))) { setCur('0'); return; }
      setCur(cur.slice(0, -1));
    };
    const chooseOp = (o) => {
      if (cur === 'Error') return;
      if (op !== null && !fresh && acc !== null) {
        const r = compute(acc, cur, op);
        if (!isFinite(r)) { clearAll(); setCur('Error'); return; }
        const rr = round(r);
        setAcc(rr); setCur(rr); setHist(fmtNum(rr) + ' ' + o);
      } else {
        setAcc(cur); setHist(fmtNum(cur) + ' ' + o);
      }
      setOp(o); setFresh(true);
    };
    const equals = () => {
      if (op === null || acc === null) return;
      const r = compute(acc, cur, op);
      if (!isFinite(r)) { clearAll(); setCur('Error'); return; }
      const rr = round(r);
      setHist(fmtNum(acc) + ' ' + op + ' ' + fmtNum(cur) + ' =');
      setCur(rr); setAcc(null); setOp(null); setFresh(true);
    };

    const Key = ({ label, on, kind, span }) => {
      const isAcc = kind === 'op' || kind === 'eq';
      const bg = kind === 'eq' ? accent : kind === 'op' ? lighten(accent, 0.86) : 'var(--w-line)';
      const fg = kind === 'eq' ? onColor(accent) : kind === 'op' ? accent : 'var(--w-fg)';
      const active = kind === 'op' && op === label && fresh;
      return (
        <button onClick={on} style={{
          gridColumn: span ? 'span 2' : 'auto',
          height: 46 * s, borderRadius: 12 * s, border: 'none', cursor: 'pointer',
          background: active ? accent : kind === 'fn' ? 'transparent' : bg,
          color: active ? onColor(accent) : kind === 'fn' ? 'var(--w-mut)' : fg,
          fontSize: 18 * s, fontWeight: kind === 'fn' ? 500 : 600,
          fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          transition: 'background 0.12s, color 0.12s', WebkitTapHighlightColor: 'transparent',
        }}>{label}</button>
      );
    };

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 12 * s }}>
        <div style={{ minHeight: 56 * s, display: 'flex', flexDirection: 'column', alignItems: 'flex-end', justifyContent: 'flex-end', gap: 3 * s, padding: `0 ${4 * s}px` }}>
          <div style={{ fontSize: 12.5 * s, color: 'var(--w-mut)', fontVariantNumeric: 'tabular-nums', minHeight: 15 * s, letterSpacing: '0.01em' }}>{hist}</div>
          <div style={{ fontSize: 38 * s, fontWeight: 600, letterSpacing: '-0.02em', lineHeight: 1.05, fontVariantNumeric: 'tabular-nums', color: cur === 'Error' ? accent : 'var(--w-fg)', maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{cur === 'Error' ? 'Error' : fmtNum(cur)}</div>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 7 * s }}>
          <Key label="AC" kind="fn" on={clearAll} />
          <Key label="±" kind="fn" on={toggleSign} />
          <Key label="%" kind="fn" on={percent} />
          <Key label="÷" kind="op" on={() => chooseOp('÷')} />
          <Key label="7" on={() => inputDigit('7')} />
          <Key label="8" on={() => inputDigit('8')} />
          <Key label="9" on={() => inputDigit('9')} />
          <Key label="×" kind="op" on={() => chooseOp('×')} />
          <Key label="4" on={() => inputDigit('4')} />
          <Key label="5" on={() => inputDigit('5')} />
          <Key label="6" on={() => inputDigit('6')} />
          <Key label="−" kind="op" on={() => chooseOp('-')} />
          <Key label="1" on={() => inputDigit('1')} />
          <Key label="2" on={() => inputDigit('2')} />
          <Key label="3" on={() => inputDigit('3')} />
          <Key label="+" kind="op" on={() => chooseOp('+')} />
          <Key label="0" span on={() => inputDigit('0')} />
          <Key label="." on={inputDot} />
          <Key label="=" kind="eq" on={equals} />
        </div>
      </div>
    );
  }

  // ---- PERCENTAGE ----
  function Percent() {
    const [pct, setPct] = useState('15');
    const [base, setBase] = useState('200');
    const p = parseFloat(pct) || 0;
    const b = parseFloat(base) || 0;
    const portion = (p / 100) * b;

    const Field = ({ label, value, onChange, suffix }) => (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 5 * s, flex: 1 }}>
        <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>{label}</div>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s, borderBottom: `1.5px solid var(--w-line)`, paddingBottom: 5 * s }}>
          <input inputMode="decimal" value={value} onChange={(e) => onChange(e.target.value.replace(/[^0-9.]/g, ''))} style={{ width: '100%', border: 'none', outline: 'none', background: 'transparent', color: 'var(--w-fg)', fontSize: 26 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em', minWidth: 0, padding: 0 }} />
          <span style={{ fontSize: 15 * s, color: 'var(--w-mut)', fontWeight: 600 }}>{suffix}</span>
        </div>
      </div>
    );

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 22 * s }}>
        <div style={{ display: 'flex', gap: 18 * s }}>
          <Field label="Percent" value={pct} onChange={setPct} suffix="%" />
          <Field label="Of" value={base} onChange={setBase} suffix="" />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 * s, padding: `${16 * s}px 0`, borderRadius: 14 * s, background: lighten(accent, 0.9) }}>
          <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Result</div>
          <div style={{ fontSize: 40 * s, fontWeight: 700, color: accent, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>{fmtNum(round(portion))}</div>
        </div>
      </div>
    );
  }

  // ---- TIP ----
  function Tip() {
    const [bill, setBill] = useState('48.00');
    const [tip, setTip] = useState(c.defaultTip != null ? c.defaultTip : 18);
    const [split, setSplit] = useState(1);
    const b = parseFloat(bill) || 0;
    const tipAmt = b * (tip / 100);
    const total = b + tipAmt;
    const per = total / split;
    const cur = c.currency || '$';

    const presets = [15, 18, 20, 25];

    const Stat = ({ label, value, big }) => (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: big ? 'flex-start' : 'flex-end', gap: 2 * s, flex: big ? 1 : 'none' }}>
        <div style={{ fontSize: 10 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>{label}</div>
        <div style={{ fontSize: (big ? 30 : 16) * s, fontWeight: big ? 700 : 600, color: big ? accent : 'var(--w-fg)', lineHeight: 1, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em' }}>{cur}{fmtNum(round(value))}</div>
      </div>
    );

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 16 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5 * s }}>
          <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Bill</div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s, borderBottom: `1.5px solid var(--w-line)`, paddingBottom: 5 * s }}>
            <span style={{ fontSize: 22 * s, color: 'var(--w-mut)', fontWeight: 600 }}>{cur}</span>
            <input inputMode="decimal" value={bill} onChange={(e) => setBill(e.target.value.replace(/[^0-9.]/g, ''))} style={{ width: '100%', border: 'none', outline: 'none', background: 'transparent', color: 'var(--w-fg)', fontSize: 28 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em', minWidth: 0, padding: 0 }} />
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 7 * s }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Tip</span>
            <span style={{ fontSize: 13 * s, fontWeight: 700, color: accent, fontVariantNumeric: 'tabular-nums' }}>{tip}%</span>
          </div>
          <div style={{ display: 'flex', gap: 6 * s }}>
            {presets.map((pp) => {
              const on = tip === pp;
              return (
                <button key={pp} onClick={() => setTip(pp)} style={{ flex: 1, height: 34 * s, borderRadius: 9 * s, border: `1.5px solid ${on ? accent : 'var(--w-line)'}`, background: on ? accent : 'transparent', color: on ? onColor(accent) : 'var(--w-fg)', fontSize: 13 * s, fontWeight: 600, fontFamily: fontStack, cursor: 'pointer', fontVariantNumeric: 'tabular-nums', transition: 'all 0.12s' }}>{pp}%</button>
              );
            })}
          </div>
        </div>

        {!mini ? (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Split</span>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 * s }}>
              <button onClick={() => setSplit((v) => Math.max(1, v - 1))} style={{ width: 28 * s, height: 28 * s, borderRadius: 8 * s, border: `1.5px solid var(--w-line)`, background: 'transparent', color: 'var(--w-fg)', fontSize: 18 * s, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 1 }}>−</button>
              <span style={{ fontSize: 17 * s, fontWeight: 700, minWidth: 18 * s, textAlign: 'center', fontVariantNumeric: 'tabular-nums' }}>{split}</span>
              <button onClick={() => setSplit((v) => Math.min(50, v + 1))} style={{ width: 28 * s, height: 28 * s, borderRadius: 8 * s, border: `1.5px solid var(--w-line)`, background: 'transparent', color: 'var(--w-fg)', fontSize: 18 * s, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 1 }}>+</button>
            </div>
          </div>
        ) : null}

        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 10 * s, padding: `${14 * s}px ${14 * s}px`, borderRadius: 14 * s, background: lighten(accent, 0.9) }}>
          <Stat label={split > 1 ? 'Per person' : 'Total'} value={per} big />
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 * s, alignItems: 'flex-end' }}>
            <Stat label="Tip" value={tipAmt} />
            {split > 1 ? <Stat label="Total" value={total} /> : null}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: 18 * s, fontFamily: fontStack, boxSizing: 'border-box' }}>
      {mode === 'percent' ? <Percent /> : mode === 'tip' ? <Tip /> : <Basic />}
    </div>
  );
}

options:
