renderer:
function UnitConverterW({ config: c, accent, s, fontStack, mini }) {
  const CATS = useMemo(() => ({
    length: {
      label: 'Length',
      units: [
        { v: 'mm', l: 'mm', k: 0.001 },
        { v: 'cm', l: 'cm', k: 0.01 },
        { v: 'm', l: 'm', k: 1 },
        { v: 'km', l: 'km', k: 1000 },
        { v: 'in', l: 'in', k: 0.0254 },
        { v: 'ft', l: 'ft', k: 0.3048 },
        { v: 'yd', l: 'yd', k: 0.9144 },
        { v: 'mi', l: 'mi', k: 1609.344 },
      ],
    },
    weight: {
      label: 'Weight',
      units: [
        { v: 'mg', l: 'mg', k: 0.001 },
        { v: 'g', l: 'g', k: 1 },
        { v: 'kg', l: 'kg', k: 1000 },
        { v: 't', l: 't', k: 1e6 },
        { v: 'oz', l: 'oz', k: 28.3495 },
        { v: 'lb', l: 'lb', k: 453.592 },
        { v: 'st', l: 'st', k: 6350.29 },
      ],
    },
    temp: {
      label: 'Temp',
      units: [
        { v: 'C', l: '°C' },
        { v: 'F', l: '°F' },
        { v: 'K', l: 'K' },
      ],
    },
    volume: {
      label: 'Volume',
      units: [
        { v: 'ml', l: 'ml', k: 0.001 },
        { v: 'l', l: 'L', k: 1 },
        { v: 'tsp', l: 'tsp', k: 0.00492892 },
        { v: 'tbsp', l: 'tbsp', k: 0.0147868 },
        { v: 'cup', l: 'cup', k: 0.236588 },
        { v: 'pt', l: 'pt', k: 0.473176 },
        { v: 'qt', l: 'qt', k: 0.946353 },
        { v: 'gal', l: 'gal', k: 3.78541 },
      ],
    },
    data: {
      label: 'Data',
      units: [
        { v: 'B', l: 'B', k: 1 },
        { v: 'KB', l: 'KB', k: 1024 },
        { v: 'MB', l: 'MB', k: 1048576 },
        { v: 'GB', l: 'GB', k: 1073741824 },
        { v: 'TB', l: 'TB', k: 1099511627776 },
      ],
    },
  }), []);

  const [catKey, setCatKey] = useState(() => (CATS[c.category] ? c.category : 'length'));
  useEffect(() => { if (CATS[c.category] && c.category !== catKey) setCatKey(c.category); }, [c.category]);
  const cat = CATS[catKey] || CATS.length;

  const pick = (val, idx) => {
    const u = cat.units.find(x => x.v === val);
    return u ? u.v : cat.units[Math.min(idx, cat.units.length - 1)].v;
  };

  const [amount, setAmount] = useState(() => {
    const a = c.amount;
    return (a === 0 || a) ? String(a) : '1';
  });
  const [from, setFrom] = useState(() => pick(c.from, 0));
  const [to, setTo] = useState(() => pick(c.to, 1));

  const prevCat = useRef(catKey);
  useEffect(() => {
    if (prevCat.current !== catKey) {
      setFrom(cat.units[0].v);
      setTo(cat.units[Math.min(1, cat.units.length - 1)].v);
      prevCat.current = catKey;
    }
  }, [catKey, cat]);

  useEffect(() => { setFrom(pick(c.from, 0)); setTo(pick(c.to, 1)); }, [c.from, c.to]);
  useEffect(() => { const a = c.amount; if (a === 0 || a) setAmount(String(a)); }, [c.amount]);

  const convert = (n, f, t) => {
    if (catKey === 'temp') {
      let cel;
      if (f === 'C') cel = n; else if (f === 'F') cel = (n - 32) * 5 / 9; else cel = n - 273.15;
      if (t === 'C') return cel; if (t === 'F') return cel * 9 / 5 + 32; return cel + 273.15;
    }
    const uf = cat.units.find(x => x.v === f), ut = cat.units.find(x => x.v === t);
    if (!uf || !ut) return n;
    return n * uf.k / ut.k;
  };

  const raw = parseFloat(amount);
  const valid = !isNaN(raw) && amount !== '' && amount !== '-' && amount !== '.';
  const result = valid ? convert(raw, from, to) : 0;

  const fmtNum = (n) => {
    if (!isFinite(n)) return '—';
    const abs = Math.abs(n);
    let out;
    if (n === 0) out = '0';
    else if (abs < 0.0001 || abs >= 1e12) out = n.toExponential(3);
    else {
      const digits = abs >= 100 ? 2 : abs >= 1 ? 4 : 6;
      out = parseFloat(n.toFixed(digits)).toString();
    }
    if (out.indexOf('e') === -1 && out.indexOf('.') === -1) {
      const neg = out[0] === '-';
      const grp = (neg ? out.slice(1) : out).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
      out = (neg ? '-' : '') + grp;
    }
    return out;
  };

  const labelOf = (v) => { const u = cat.units.find(x => x.v === v); return u ? u.l : v; };
  const swap = () => { setFrom(to); setTo(from); };
  const showCats = c.showCategories !== false;

  const inputStyle = {
    textAlign: 'center', border: 'none', outline: 'none', background: 'transparent',
    color: 'var(--w-fg)', fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
    letterSpacing: '-0.02em', padding: 0, fontSize: 30 * s, fontWeight: 700,
    maxWidth: '76%', minWidth: 28 * s, width: 'auto',
  };

  const pillBtn = (active) => ({
    cursor: 'pointer', borderRadius: 999, fontWeight: 600,
    fontSize: 11.5 * s, padding: `${4.5 * s}px ${10 * s}px`, lineHeight: 1,
    fontFamily: fontStack, transition: 'all 0.12s ease',
    border: `1px solid ${active ? accent : 'var(--w-line)'}`,
    background: active ? accent : 'transparent',
    color: active ? onColor(accent) : 'var(--w-mut)',
  });

  const renderField = (isFrom) => (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 * s, width: '100%' }}>
      <div style={{ fontSize: 9.5 * s, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>
        {isFrom ? 'From' : 'To'}
      </div>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'center', gap: 6 * s, width: '100%' }}>
        {isFrom ? (
          <input
            type="text" inputMode="decimal" value={amount}
            onChange={e => { const v = e.target.value; if (/^-?\d*\.?\d*$/.test(v)) setAmount(v); }}
            style={inputStyle}
          />
        ) : (
          <div style={{ fontSize: 30 * s, fontWeight: 700, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums', color: valid ? accent : 'var(--w-mut)', maxWidth: '76%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {valid ? fmtNum(result) : '—'}
          </div>
        )}
        <span style={{ fontSize: 13 * s, fontWeight: 600, color: 'var(--w-mut)', whiteSpace: 'nowrap' }}>{labelOf(isFrom ? from : to)}</span>
      </div>
      {!mini && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 * s, justifyContent: 'center' }}>
          {cat.units.map(u => {
            const sel = (isFrom ? from : to) === u.v;
            return <button key={u.v} onClick={() => (isFrom ? setFrom : setTo)(u.v)} style={pillBtn(sel)}>{u.l}</button>;
          })}
        </div>
      )}
    </div>
  );

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 12 * s, padding: 18 * s, fontFamily: fontStack }}>
      {showCats && !mini && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 * s, justifyContent: 'center' }}>
          {Object.keys(CATS).map(k => {
            const on = k === catKey;
            return (
              <button key={k} onClick={() => setCatKey(k)} style={{
                cursor: 'pointer', borderRadius: 999, fontWeight: 600, fontFamily: fontStack,
                fontSize: 11 * s, padding: `${4 * s}px ${10 * s}px`, lineHeight: 1, transition: 'all 0.12s ease',
                border: 'none', background: on ? accent : 'transparent',
                color: on ? onColor(accent) : 'var(--w-mut)',
                boxShadow: on ? 'none' : 'inset 0 0 0 1px var(--w-line)',
              }}>{CATS[k].label}</button>
            );
          })}
        </div>
      )}

      {renderField(true)}

      <button onClick={swap} aria-label="Swap units" style={{
        cursor: 'pointer', width: 30 * s, height: 30 * s, borderRadius: 999,
        display: 'grid', placeItems: 'center', flexShrink: 0,
        border: '1px solid var(--w-line)', background: 'transparent', color: 'var(--w-mut)',
        transition: 'all 0.12s ease',
      }}
        onMouseEnter={e => { e.currentTarget.style.color = accent; e.currentTarget.style.borderColor = accent; }}
        onMouseLeave={e => { e.currentTarget.style.color = 'var(--w-mut)'; e.currentTarget.style.borderColor = 'var(--w-line)'; }}
      >
        <svg width={15 * s} height={15 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M7 4v16M7 4l-3 3M7 4l3 3" />
          <path d="M17 20V4M17 20l3-3M17 20l-3-3" />
        </svg>
      </button>

      {renderField(false)}
    </div>
  );
}
